    !isJsonObject(value) ||
    !hasExactKeys(value, ['version', 'tournament', 'gameSnapshot']) ||
    value.version !== TOURNAMENT_VERSION ||
    !(value.gameSnapshot === null || typeof value.gameSnapshot === 'string')
