import { useEffect, useRef, useState } from 'react';
import { formatElapsed } from './elapsed-time.ts';
import { Board } from './board/Board.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import type { Session } from './session/session.ts';
import {
  activeTournamentMatch,
  matchPlaceholder,
  nextPlayerName,
  validateNames,
} from './tournament.ts';
import type { Tournament } from './tournament.ts';
import './tournament.css';

const JSON_MAX_CHARACTERS = 100_000;

interface TournamentScreenProps {
  session: Session;
  active: Tournament | null;
  championView: Tournament | null;
  past: readonly Tournament[];
  startTournament(playerCount: 4 | 8, names: readonly string[]): void;
  startTurn(): void;
  nextTurn(): void;
  nextMatch(): void;
  leaveTournament(): void;
  backToGame(): void;
  setupAnother(): void;
  exportTournament(tournament: Tournament): string;
  loadTournament(text: string): boolean;
  activate(index: number): void;
}

export function TournamentScreen({
  session,
  active,
  championView,
  past,
  startTournament,
  startTurn,
  nextTurn,
  nextMatch,
  leaveTournament,
  backToGame,
  setupAnother,
  exportTournament,
  loadTournament,
  activate,
}: TournamentScreenProps) {
  const [playerCount, setPlayerCount] = useState<4 | 8>(4);
  const [names, setNames] = useState(() =>
    Array.from({ length: 8 }, (_, index) => `Player ${index + 1}`),
  );
  const [nameError, setNameError] = useState('');
  const [json, setJson] = useState('');
  const [jsonNotice, setJsonNotice] = useState('');
  const board = useRef<BoardFocus>(null);
  const game = session.game;
  const isActive = active?.phase === 'active';
  const currentMatch = active ? activeTournamentMatch(active) : null;
  const player = active ? nextPlayerName(active) : null;
  const selectedTournament = active ?? championView ?? past[0] ?? null;

  useEffect(() => {
    if (isActive && active?.turnState === 'playing') board.current?.focusRemembered();
  }, [active?.turnState, session.generation, isActive]);

  function updateName(index: number, value: string): void {
    setNames((previous) => previous.map((name, nameIndex) => (nameIndex === index ? value : name)));
    setNameError('');
  }

  function beginTournament(): void {
    if (!validateNames(names, playerCount)) {
      setNameError('Enter a unique name for each player in this tournament.');
      return;
    }
    startTournament(playerCount, names);
  }

  function exportSelected(): void {
    if (!selectedTournament) {
      setJsonNotice('Start a tournament before exporting one.');
      return;
    }
    setJson(exportTournament(selectedTournament));
    setJsonNotice('Tournament JSON is ready.');
  }

  function loadFromBox(): void {
    setJsonNotice(loadTournament(json) ? 'Tournament loaded.' : 'Invalid tournament JSON.');
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-title">
      <div className="tournament-heading">
        <div>
          <p className="eyebrow">One deal. Two turns. One champion.</p>
          <h2 id="tournament-title">Tournament</h2>
        </div>
        {!isActive && !championView && (
          <button type="button" className="control" onClick={backToGame}>
            Back to game
          </button>
        )}
      </div>

      {!isActive && !championView && (
        <section className="tournament-setup" aria-labelledby="setup-title">
          <h3 id="setup-title">Set up a knockout tournament</h3>
          <div className="tournament-players-control">
            <label htmlFor="tournament-player-count">Players</label>
            <select
              id="tournament-player-count"
              className="control"
              value={playerCount}
              onChange={(event) => setPlayerCount(Number(event.currentTarget.value) as 4 | 8)}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
          </div>
          <div className="player-name-grid">
            {names.map((name, index) => (
              <label key={index} htmlFor={`tournament-player-${index + 1}`}>
                Player {index + 1}
                <input
                  id={`tournament-player-${index + 1}`}
                  className="control"
                  value={name}
                  maxLength={40}
                  autoComplete="off"
                  onChange={(event) => updateName(index, event.currentTarget.value)}
                />
              </label>
            ))}
          </div>
          <p className="tournament-error" role="status" aria-live="polite">
            {nameError}
          </p>
          <button type="button" className="control primary-control" onClick={beginTournament}>
            Start tournament
          </button>
        </section>
      )}

      {isActive && active && currentMatch && (
        <section className="active-tournament" aria-labelledby="active-tournament-title">
          <div className="active-tournament-heading">
            <div>
              <h3 id="active-tournament-title">
                Round {currentMatch.round}, match {currentMatch.number}
              </h3>
              <p className="now-playing" aria-live="polite" aria-atomic="true">
                Now playing: {player}
              </p>
            </div>
            <button type="button" className="control leave-control" onClick={leaveTournament}>
              Leave tournament
            </button>
          </div>
          <GameStatus
            game={game}
            best={session.preferences.bestMoves[String(game.size)]}
            celebration={session.celebration}
          />
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <div className="game-result">
            <p role="status" aria-live="polite" aria-atomic="true">
              <span key={session.announcement}>{session.feedback}</span>
            </p>
          </div>
          <Board
            key={session.generation}
            game={game}
            activate={(index) => {
              if (active.turnState === 'playing') activate(index);
            }}
            ref={board}
          />
          <div className="tournament-actions" aria-live="polite">
            {active.turnState === 'ready' && (
              <button type="button" className="control primary-control" onClick={startTurn}>
                Start turn
              </button>
            )}
            {active.turnState === 'turn-over' && (
              <button type="button" className="control primary-control" onClick={nextTurn}>
                Next turn
              </button>
            )}
            {active.turnState === 'match-over' && (
              <button type="button" className="control primary-control" onClick={nextMatch}>
                Next match
              </button>
            )}
          </div>
        </section>
      )}

      {championView?.phase === 'complete' && (
        <section className="champion-panel" aria-labelledby="champion-title">
          <h3 id="champion-title">Champion: {championView.champion}</h3>
          <p>The tournament is complete.</p>
          <div className="tournament-actions">
            <button type="button" className="control" onClick={backToGame}>
              Back to game
            </button>
            <button type="button" className="control" onClick={setupAnother}>
              Set up another tournament
            </button>
          </div>
        </section>
      )}

      {(active || championView) && (
        <TournamentBracket tournament={active ?? championView!} title="Tournament bracket" />
      )}

      <section className="tournament-json" aria-labelledby="tournament-json-title">
        <h3 id="tournament-json-title">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={8}
          maxLength={JSON_MAX_CHARACTERS}
          spellCheck={false}
          value={json}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button type="button" className="control" onClick={exportSelected}>
            Export tournament
          </button>
          <button type="button" className="control" onClick={loadFromBox}>
            Load tournament
          </button>
        </div>
        <p className="tournament-json-notice" role="status" aria-live="polite">
          {jsonNotice}
        </p>
      </section>

      <section className="past-tournaments" aria-labelledby="past-tournaments-title">
        <h3 id="past-tournaments-title">Past tournaments</h3>
        {past.length === 0 ? (
          <p className="empty-tournaments">Completed tournaments will appear here.</p>
        ) : (
          <div className="past-tournament-list">
            {past.map((tournament, index) => (
              <details className="past-tournament" key={`${tournament.createdAt}-${index}`}>
                <summary>
                  {new Date(tournament.createdAt).toLocaleString()} · {tournament.playerCount}{' '}
                  players · Champion: {tournament.champion}
                </summary>
                <TournamentBracket tournament={tournament} title="Tournament bracket" />
              </details>
            ))}
          </div>
        )}
      </section>
    </section>
  );
}

function TournamentBracket({ tournament, title }: { tournament: Tournament; title: string }) {
  const roundCount = Math.log2(tournament.playerCount);
  return (
    <section className="tournament-bracket" aria-label={title}>
      <div className={`bracket-rounds rounds-${roundCount}`}>
        {Array.from({ length: roundCount }, (_, index) => index + 1).map((round) => (
          <div className="bracket-round" key={round}>
            <h4>{roundName(round, roundCount)}</h4>
            {tournament.matches
              .filter((match) => match.round === round)
              .map((match) => (
                <article className={`bracket-match ${match.status}`} key={match.id}>
                  <h5>
                    Match {match.round}.{match.number}
                  </h5>
                  <ol>
                    {([0, 1] as const).map((slot) => {
                      const result = match.results[slot];
                      return (
                        <li
                          key={slot}
                          className={match.winner === match.players[slot] ? 'match-winner' : ''}
                        >
                          <span className="bracket-player">{matchPlaceholder(match, slot)}</span>
                          {result && (
                            <span className="bracket-result">
                              {result.moves} moves · {formatElapsed(result.elapsedMs)}
                            </span>
                          )}
                        </li>
                      );
                    })}
                  </ol>
                  {match.winner ? (
                    <p className="match-winner-label">Winner: {match.winner}</p>
                  ) : (
                    <p className="match-status-label">
                      {match.status === 'active' ? 'In progress' : 'Upcoming'}
                    </p>
                  )}
                </article>
              ))}
          </div>
        ))}
      </div>
      {tournament.phase === 'complete' && (
        <p className="bracket-champion">Champion: {tournament.champion}</p>
      )}
    </section>
  );
import { isValidSize, parseBoardCode } from './deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from './game.ts';
import { decodeSnapshot } from './snapshot.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';

export const TOURNAMENT_VERSION = 1;
export const TOURNAMENT_MAX_BYTES = 100_000;
export const PLAYER_NAME_MAX = 40;

export interface PlayerResult {
  readonly moves: number;
  readonly elapsedMs: number;
}

export interface TournamentMatch {
  readonly id: string;
  readonly round: number;
  readonly number: number;
  readonly players: readonly [string | null, string | null];
  readonly results: readonly [PlayerResult | null, PlayerResult | null];
  readonly winner: string | null;
  readonly boardCode: string | null;
  readonly status: 'pending' | 'active' | 'complete';
}

export type TournamentTurnState = 'ready' | 'playing' | 'turn-over' | 'match-over' | 'complete';

export interface Tournament {
  readonly version: typeof TOURNAMENT_VERSION;
  readonly playerCount: 4 | 8;
  readonly boardSize: number;
  readonly players: readonly string[];
  readonly createdAt: string;
  readonly phase: 'active' | 'complete';
  readonly matches: readonly TournamentMatch[];
  readonly currentMatchId: string | null;
  readonly turnIndex: 0 | 1;
  readonly turnState: TournamentTurnState;
  readonly champion: string | null;
}

export interface TournamentFile {
  readonly tournament: Tournament;
  readonly gameSnapshot: string | null;
}

type PlayerCount = 4 | 8;

export function createTournament(
  playerCount: PlayerCount,
  names: readonly string[],
  boardSize: number,
  boardCode: string,
): Tournament | null {
  if (
    (playerCount !== 4 && playerCount !== 8) ||
    names.length < playerCount ||
    !isValidSize(boardSize) ||
    parseBoardCode(boardCode)?.size !== boardSize
  )
    return null;
  const players = names.slice(0, playerCount).map((name) => name.trim());
  if (!validNames(players)) return null;
  const matches: TournamentMatch[] = [];
  const rounds = Math.log2(playerCount);
  for (let round = 1; round <= rounds; round += 1) {
    const count = playerCount / 2 ** round;
    for (let number = 1; number <= count; number += 1) {
      const index = matches.length;
      const firstRound = round === 1;
      const firstPlayer = firstRound ? (players[(number - 1) * 2] ?? null) : null;
      const secondPlayer = firstRound ? (players[(number - 1) * 2 + 1] ?? null) : null;
      matches.push({
        id: matchId(round, number),
        round,
        number,
        players: [firstPlayer, secondPlayer],
        results: [null, null],
        winner: null,
        boardCode: index === 0 ? boardCode : null,
        status: index === 0 ? 'active' : 'pending',
      });
    }
  }
  return {
    version: TOURNAMENT_VERSION,
    playerCount,
    boardSize,
    players,
    createdAt: new Date().toISOString(),
    phase: 'active',
    matches,
    currentMatchId: matchId(1, 1),
    turnIndex: 0,
    turnState: 'ready',
    champion: null,
  };
}

export function startTournamentTurn(tournament: Tournament): Tournament {
  if (tournament.phase !== 'active' || tournament.turnState !== 'ready') return tournament;
  return { ...tournament, turnState: 'playing' };
}

export function recordTournamentTurn(tournament: Tournament, result: PlayerResult): Tournament {
  const matchIndex = tournament.matches.findIndex(
    (match) => match.id === tournament.currentMatchId,
  );
  const match = tournament.matches[matchIndex];
  if (
    tournament.phase !== 'active' ||
    tournament.turnState !== 'playing' ||
    !match ||
    match.status !== 'active' ||
    match.results[tournament.turnIndex] !== null ||
    !validResult(result, tournament.boardSize)
  )
    return tournament;

  const results: [PlayerResult | null, PlayerResult | null] = [...match.results];
  results[tournament.turnIndex] = result;
  if (tournament.turnIndex === 0) {
    const matches = [...tournament.matches];
    matches[matchIndex] = { ...match, results };
    return { ...tournament, matches, turnIndex: 1, turnState: 'turn-over' };
  }

  const left = results[0];
  const right = results[1];
  const firstPlayer = match.players[0];
  const secondPlayer = match.players[1];
  if (!left || !right || !firstPlayer || !secondPlayer) return tournament;
  // Fewer moves wins. Equal move counts use elapsed time; an exact tie advances the first player.
  const winner =
    left.moves < right.moves || (left.moves === right.moves && left.elapsedMs <= right.elapsedMs)
      ? firstPlayer
      : secondPlayer;
  const matches = [...tournament.matches];
  matches[matchIndex] = { ...match, results, winner, status: 'complete' };
  const nextRound = match.round + 1;
  const nextNumber = Math.ceil(match.number / 2);
  const nextIndex = matches.findIndex((item) => item.id === matchId(nextRound, nextNumber));
  if (nextIndex >= 0) {
    const nextMatch = matches[nextIndex];
    if (nextMatch) {
      const slot = match.number % 2 === 1 ? 0 : 1;
      const players: [string | null, string | null] = [...nextMatch.players];
      players[slot] = winner;
      matches[nextIndex] = { ...nextMatch, players };
    }
  }
  return { ...tournament, matches, turnState: 'match-over' };
}

export function advanceTournamentTurn(tournament: Tournament): Tournament {
  if (tournament.phase !== 'active' || tournament.turnState !== 'turn-over') return tournament;
  const match = tournament.matches.find((item) => item.id === tournament.currentMatchId);
  if (!match || match.results[0] === null) return tournament;
  return { ...tournament, turnState: 'ready' };
}

export function advanceTournamentMatch(tournament: Tournament, nextBoardCode: string): Tournament {
  if (tournament.phase !== 'active' || tournament.turnState !== 'match-over') return tournament;
  const current = tournament.matches.find((match) => match.id === tournament.currentMatchId);
  if (!current?.winner) return tournament;
  if (current.round === Math.log2(tournament.playerCount)) {
    return {
      ...tournament,
      phase: 'complete',
      currentMatchId: null,
      turnState: 'complete',
      champion: current.winner,
    };
  }
  const next = tournament.matches.find(
    (match) => match.status === 'pending' && match.players[0] !== null && match.players[1] !== null,
  );
  if (!next || parseBoardCode(nextBoardCode)?.size !== tournament.boardSize) return tournament;
  const matches = tournament.matches.map((match) =>
    match.id === next.id
      ? { ...match, status: 'active' as const, boardCode: nextBoardCode }
      : match,
  );
  return {
    ...tournament,
    matches,
    currentMatchId: next.id,
    turnIndex: 0,
    turnState: 'ready',
  };
}

export function encodeTournamentFile(tournament: Tournament, gameSnapshot: string | null): string {
  return JSON.stringify({ version: TOURNAMENT_VERSION, tournament, gameSnapshot }, null, 2);
}

export function decodeTournamentFile(text: string): TournamentFile | null {
  const value = isWithinBytes(text, TOURNAMENT_MAX_BYTES) ? parseJson(text) : undefined;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['version', 'tournament', 'gameSnapshot']) ||
    value.version !== TOURNAMENT_VERSION ||
    !(value.gameSnapshot === null || typeof value.gameSnapshot === 'string')
  )
    return null;
  const tournament = decodeTournament(value.tournament);
  if (!tournament) return null;
  if (value.gameSnapshot !== null) {
    const game = decodeSnapshot(value.gameSnapshot);
    const match = tournament.matches.find((item) => item.id === tournament.currentMatchId);
    if (!game || !match || game.boardCode !== match.boardCode) return null;
  }
  return { tournament, gameSnapshot: value.gameSnapshot };
}

export function decodeTournament(value: unknown): Tournament | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, [
      'version',
      'playerCount',
      'boardSize',
      'players',
      'createdAt',
      'phase',
      'matches',
      'currentMatchId',
      'turnIndex',
      'turnState',
      'champion',
    ]) ||
    value.version !== TOURNAMENT_VERSION ||
    (value.playerCount !== 4 && value.playerCount !== 8) ||
    typeof value.boardSize !== 'number' ||
    !isValidSize(value.boardSize) ||
    typeof value.createdAt !== 'string' ||
    value.createdAt.length > 40 ||
    (value.phase !== 'active' && value.phase !== 'complete') ||
    !Array.isArray(value.players) ||
    !validNames(value.players) ||
    value.players.length !== value.playerCount ||
    !Array.isArray(value.matches) ||
    !isNonnegativeSafeInteger(value.turnIndex) ||
    value.turnIndex > 1 ||
    !isTurnState(value.turnState) ||
    !(value.currentMatchId === null || typeof value.currentMatchId === 'string') ||
    !(value.champion === null || typeof value.champion === 'string')
  )
    return null;

  const matches: TournamentMatch[] = [];
  const rounds = Math.log2(value.playerCount);
  if (value.matches.length !== value.playerCount - 1) return null;
  for (let round = 1; round <= rounds; round += 1) {
    const count = value.playerCount / 2 ** round;
    for (let number = 1; number <= count; number += 1) {
      const index = matches.length;
      const parsed = decodeMatch(value.matches[index], round, number, value.boardSize);
      if (!parsed) return null;
      matches.push(parsed);
    }
  }
  const tournament: Tournament = {
    version: TOURNAMENT_VERSION,
    playerCount: value.playerCount,
    boardSize: value.boardSize,
    players: value.players,
    createdAt: value.createdAt,
    phase: value.phase,
    matches,
    currentMatchId: value.currentMatchId,
    turnIndex: value.turnIndex as 0 | 1,
    turnState: value.turnState,
    champion: value.champion,
  };
  return validTournamentState(tournament) ? tournament : null;
}

export function validateNames(names: readonly string[], count: number): boolean {
  return (count === 4 || count === 8) && validNames(names.slice(0, count));
}

export function activeTournamentMatch(tournament: Tournament): TournamentMatch | null {
  return tournament.matches.find((match) => match.id === tournament.currentMatchId) ?? null;
}

export function nextPlayerName(tournament: Tournament): string | null {
  return activeTournamentMatch(tournament)?.players[tournament.turnIndex] ?? null;
}

export function matchPlaceholder(match: TournamentMatch, slot: 0 | 1): string {
  const player = match.players[slot];
  if (player) return player;
  if (match.round === 1) return 'TBD';
  if (match.round === 1) return 'TBD';
  const sourceNumber = (match.number - 1) * 2 + slot + 1;
  return `Winner of match ${match.round - 1}.${sourceNumber}`;
}

function decodeMatch(
  value: unknown,
  round: number,
  number: number,
  boardSize: number,
): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, [
      'id',
      'round',
      'number',
      'players',
      'results',
      'winner',
      'boardCode',
      'status',
    ]) ||
    value.id !== matchId(round, number) ||
    value.round !== round ||
    value.number !== number ||
    !Array.isArray(value.players) ||
    value.players.length !== 2 ||
    !value.players.every((player) => player === null || typeof player === 'string') ||
    !Array.isArray(value.results) ||
    value.results.length !== 2 ||
    !(value.winner === null || typeof value.winner === 'string') ||
    !(value.boardCode === null || typeof value.boardCode === 'string') ||
    (value.status !== 'pending' && value.status !== 'active' && value.status !== 'complete')
  )
    return null;
  const players = value.players as [string | null, string | null];
  const results: [PlayerResult | null, PlayerResult | null] = [
    decodeResult(value.results[0], boardSize),
    decodeResult(value.results[1], boardSize),
  ];
  if (
    (value.results[0] !== null && !results[0]) ||
    (value.results[1] !== null && !results[1]) ||
    players.some(
      (player) => player !== null && (!player.trim() || player.length > PLAYER_NAME_MAX),
    ) ||
    (value.boardCode !== null && parseBoardCode(value.boardCode)?.size !== boardSize)
  )
    return null;
  return {
    id: value.id,
    round,
    number,
    players,
    results,
    winner: value.winner,
    boardCode: value.boardCode,
    status: value.status,
  };
}

function decodeResult(value: unknown, boardSize: number): PlayerResult | null {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['moves', 'elapsedMs']) ||
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves < boardSize ** 2 / 2 ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return null;
  return { moves: value.moves, elapsedMs: value.elapsedMs };
}

function validResult(result: PlayerResult, boardSize: number): boolean {
  return (
    Number.isSafeInteger(result.moves) &&
    result.moves >= boardSize ** 2 / 2 &&
    result.moves <= MOVES_MAX &&
    Number.isSafeInteger(result.elapsedMs) &&
    result.elapsedMs >= 0 &&
    result.elapsedMs <= ELAPSED_MAX_MS
  );
}

function validTournamentState(tournament: Tournament): boolean {
  const { matches, playerCount, phase, turnState, currentMatchId, turnIndex } = tournament;
  for (const match of matches) {
    if (match.round === 1) {
      const first = tournament.players[(match.number - 1) * 2];
      const second = tournament.players[(match.number - 1) * 2 + 1];
      if (match.players[0] !== first || match.players[1] !== second) return false;
    } else {
      const sourceNumber = (match.number - 1) * 2 + 1;
      const sourceA = matches.find((item) => item.id === matchId(match.round - 1, sourceNumber));
      const sourceB = matches.find(
        (item) => item.id === matchId(match.round - 1, sourceNumber + 1),
      );
      if (!sourceA || !sourceB) return false;
      if (match.players[0] !== (sourceA.status === 'complete' ? sourceA.winner : null))
        return false;
      if (match.players[1] !== (sourceB.status === 'complete' ? sourceB.winner : null))
        return false;
    }
    if (match.status === 'pending') {
      if (
        match.winner !== null ||
        match.boardCode !== null ||
        match.results.some((result) => result !== null)
      )
        return false;
      if (match.players[0] === null || match.players[1] === null) {
        // A future bracket match can be waiting for a previous winner.
        if (match.round === 1) return false;
      }
    } else if (match.status === 'active') {
      if (
        match.winner !== null ||
        !match.boardCode ||
        match.players.some((player) => player === null)
      )
        return false;
    } else if (
      match.winner === null ||
      !match.boardCode ||
      match.players.some((player) => player === null) ||
      match.results.some((result) => result === null) ||
      !match.players.includes(match.winner)
    ) {
      return false;
    }
  }
  const activeMatches = matches.filter((match) => match.status === 'active');
  if (phase === 'active') {
    if (!currentMatchId || tournament.champion !== null) return false;
    const current = matches.find((match) => match.id === currentMatchId);
    if (!current) return false;
    if (turnState === 'complete' || current.round > Math.log2(playerCount)) return false;
    if (turnState === 'match-over') {
      return (
        activeMatches.length === 0 &&
        current.status === 'complete' &&
        turnIndex === 1 &&
        current.results.every((result) => result !== null)
      );
    }
    if (activeMatches.length !== 1 || activeMatches[0]?.id !== currentMatchId) return false;
    if (turnState === 'turn-over') {
      return turnIndex === 1 && current.results[0] !== null && current.results[1] === null;
    }
    if (turnState === 'ready' || turnState === 'playing') {
      return (
        current.status === 'active' &&
        current.results[turnIndex] === null &&
        (turnIndex === 0 ? current.results[0] === null : current.results[0] !== null)
      );
    }
    return false;
  }
  const final = matches.find((match) => match.id === matchId(Math.log2(playerCount), 1));
  return (
    !currentMatchId &&
    activeMatches.length === 0 &&
    matches.every((match) => match.status === 'complete') &&
    turnState === 'complete' &&
    turnIndex === 1 &&
    tournament.champion !== null &&
    tournament.champion === final?.winner
  );
}

function validNames(names: readonly unknown[]): names is readonly string[] {
  if (
    names.length < 4 ||
    names.length > 8 ||
    !names.every(
      (name) =>
        typeof name === 'string' &&
        name.length <= PLAYER_NAME_MAX &&
        name.trim().length > 0 &&
        name === name.trim(),
    )
  )
    return false;
  const normalized = names.map((name) => (name as string).toLocaleLowerCase());
  return new Set(normalized).size === names.length;
}

function isTurnState(value: unknown): value is TournamentTurnState {
  return (
    value === 'ready' ||
    value === 'playing' ||
    value === 'turn-over' ||
    value === 'match-over' ||
    value === 'complete'
  );
}

function matchId(round: number, number: number): string {
  return `r${round}m${number}`;
}
import { isJsonObject, parseJson } from './saved-format.ts';
import { decodeTournament } from './tournament.ts';
import type { PreferenceStore } from './session/storage.ts';
import type { Tournament } from './tournament.ts';

export const TOURNAMENTS_KEY = 'neon-pairs.tournaments.v1';
const TOURNAMENTS_VERSION = 1;

export interface TournamentStore {
  readonly active: Tournament | null;
  readonly past: readonly Tournament[];
}

export const EMPTY_TOURNAMENT_STORE: TournamentStore = { active: null, past: [] };

export function readTournamentStore(store: PreferenceStore | null): TournamentStore {
  try {
    const text = store?.getItem(TOURNAMENTS_KEY);
    if (!text) return EMPTY_TOURNAMENT_STORE;
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      value.schemaVersion !== TOURNAMENTS_VERSION ||
      !(value.active === null || isJsonObject(value.active)) ||
      !Array.isArray(value.past)
    )
      return EMPTY_TOURNAMENT_STORE;
    const active = value.active === null ? null : decodeTournament(value.active);
    const past = value.past.map(decodeTournament);
    if (
      (value.active !== null && (!active || active.phase !== 'active')) ||
      past.some((tournament) => !tournament || tournament.phase !== 'complete')
    )
      return EMPTY_TOURNAMENT_STORE;
    return { active, past: past as Tournament[] };
  } catch {
    return EMPTY_TOURNAMENT_STORE;
  }
}

export function writeTournamentStore(
  store: PreferenceStore | null,
  tournaments: TournamentStore,
): void {
  try {
    store?.setItem(
      TOURNAMENTS_KEY,
      JSON.stringify({ schemaVersion: TOURNAMENTS_VERSION, ...tournaments }),
    );
  } catch {
    // A blocked browser store doesn't stop the current tournament.
  }
}
import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function loadTournamentSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) return false;
    clock.reset();
    commit(replaceGame(current.current, game, false));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  function pause(): void {
    clock.synchronize();
    commit({ ...current.current, paused: true });
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    loadTournamentSnapshot,
    exportSnapshot,
    activate,
    pause,
    resume,
  };
}

